pub fn to_bytes(&self) -> Vec<u8> {
    let byte_len = (self.nbits + 7) / 8;
    let mut bytes = vec![0u8; byte_len];

    for i in 0..self.nbits {
        if self.get(i).unwrap_or(false) {
            bytes[i / 8] |= 1 << (7 - (i % 8));
        }
    }

    bytes
}

